<section class="container narrow section-top"><?php ff_heading('verify_pass','Public verification reveals only the demonstration pass status.'); ?><div class="panel"><?php if(!empty($verification)): ?><div class="badge-row"><?php ff_badge($verification['effective_status']??$verification['status']??'unknown'); ?></div><h2><?=e(t('Demonstration pass found.'))?></h2><p><?=e(t('This verification grants no real gym access. Personal member information is not displayed.'))?></p><?php else: ?><h2><?=e(t('This demonstration pass could not be verified.'))?></h2><p><?=e(t('Check the full verification link or sign in to view your own passes.'))?></p><?php endif ?><a class="button secondary" href="<?=e(url('passes'))?>"><?=e(t('my_passes'))?></a></div></section>
